<script setup>import {ref} from 'vue';import {testimonials} from '../data/portfolio';const active=ref(0);const change=n=>active.value=(active.value+n+testimonials.length)%testimonials.length</script>
<template><section class="section testimonials"><div class="section-title split"><div><p class="eyebrow">07 — KIND WORDS</p><h2>Kolaborasi yang<br/><em>diingat baik.</em></h2></div><div class="carousel-actions"><button @click="change(-1)"><i class="fa-solid fa-arrow-left"/></button><button @click="change(1)"><i class="fa-solid fa-arrow-right"/></button></div></div><article class="testimonial-card"><i class="fa-solid fa-quote-left quote"/><p>“{{testimonials[active].text}}”</p><div><img :src="testimonials[active].image" :alt="testimonials[active].name"/><span><b>{{testimonials[active].name}}</b><small>{{testimonials[active].role}}</small></span><div class="dots"><button v-for="(_,i) in testimonials" :class="{active:i===active}" @click="active=i"/></div></div></article></section></template>
